import { del, get, patch, post, put } from './client.js'

export function listLeases(params) {
  return get('/leases/', params)
}

export function leaseStats() {
  return get('/leases/stats/')
}

export function leaseOptions(params) {
  return get('/leases/options/', params)
}

export function leaseById(id) {
  return get(`/leases/${id}/`)
}

export function leaseStatement(id) {
  return get(`/leases/${id}/statement/`)
}

/** `number` is generated by the backend and must not be sent. */
export function createLease(payload) {
  return post('/leases/', payload)
}

export function updateLease(id, payload) {
  return put(`/leases/${id}/`, payload)
}

export function patchLease(id, payload) {
  return patch(`/leases/${id}/`, payload)
}

export function deleteLease(id) {
  return del(`/leases/${id}/`)
}

export function generateLeaseInvoices(id) {
  return post(`/leases/${id}/generate-invoices/`, {})
}

export const LEASE_ORDERING = [
  { value: '-created_at', label: 'Newest first' },
  { value: 'start_date', label: 'Start date' },
  { value: 'end_date', label: 'End date' },
  { value: '-monthly_rent', label: 'Rent: high to low' },
  { value: 'status', label: 'Status' },
]
